     1	#!/usr/bin/env bash
     2	# SessionStart hook for superpowers plugin
     3	
     4	set -euo pipefail
     5	
     6	# Determine plugin root directory
     7	SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
     8	PLUGIN_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
     9	
    10	# Read using-superpowers content
    11	using_superpowers_content=$(cat "${PLUGIN_ROOT}/skills/using-superpowers/SKILL.md" 2>&1 || echo "Error reading using-superpowers skill")
    12	
    13	# Escape string for JSON embedding using bash parameter substitution.
    14	# Each ${s//old/new} is a single C-level pass - orders of magnitude
    15	# faster than the character-by-character loop this replaces.
    16	escape_for_json() {
    17	    local s="$1"
    18	    s="${s//\\/\\\\}"
    19	    s="${s//\"/\\\"}"
    20	    s="${s//$'\n'/\\n}"
    21	    s="${s//$'\r'/\\r}"
    22	    s="${s//$'\t'/\\t}"
    23	    printf '%s' "$s"
    24	}
    25	
    26	using_superpowers_escaped=$(escape_for_json "$using_superpowers_content")
    27	session_context="<EXTREMELY_IMPORTANT>\nYou have superpowers.\n\n**Below is the full content of your 'superpowers:using-superpowers' skill - your introduction to using skills. For all other skills, use the 'Skill' tool:**\n\n${using_superpowers_escaped}\n</EXTREMELY_IMPORTANT>"
    28	
    29	# Output context injection as JSON.
    30	# Cursor hooks expect additional_context (snake_case).
    31	# Claude Code hooks expect hookSpecificOutput.additionalContext (nested).
    32	# Copilot CLI (v1.0.11+) and others expect additionalContext (top-level, SDK standard).
    33	# Claude Code reads BOTH additional_context and hookSpecificOutput without
    34	# deduplication, so we must emit only the field the current platform consumes.
    35	#
    36	# Uses printf instead of heredoc to work around bash 5.3+ heredoc hang.
    37	# See: https://github.com/obra/superpowers/issues/571
    38	if [ -n "${CURSOR_PLUGIN_ROOT:-}" ]; then
    39	  # Cursor sets CURSOR_PLUGIN_ROOT (may also set CLAUDE_PLUGIN_ROOT)
    40	  printf '{\n  "additional_context": "%s"\n}\n' "$session_context" | cat
    41	elif [ -n "${CLAUDE_PLUGIN_ROOT:-}" ] && [ -z "${COPILOT_CLI:-}" ]; then
    42	  # Claude Code sets CLAUDE_PLUGIN_ROOT without COPILOT_CLI
    43	  printf '{\n  "hookSpecificOutput": {\n    "hookEventName": "SessionStart",\n    "additionalContext": "%s"\n  }\n}\n' "$session_context" | cat
    44	else
    45	  # Copilot CLI (sets COPILOT_CLI=1) or unknown platform — SDK standard format
    46	  printf '{\n  "additionalContext": "%s"\n}\n' "$session_context" | cat
    47	fi
    48	
    49	exit 0


