  1	/**
  2	 * Superpowers plugin for OpenCode.ai
  3	 *
  4	 * Injects superpowers bootstrap context via message transform.
  5	 * Auto-registers skills directory via config hook (no symlinks needed).
  6	 */
  7	
  8	import path from 'path';
  9	import fs from 'fs';
 10	import os from 'os';
 11	import { fileURLToPath } from 'url';
 12	
 13	const __dirname = path.dirname(fileURLToPath(import.meta.url));
 14	
 15	// Simple frontmatter extraction (avoid dependency on skills-core for bootstrap)
 16	const extractAndStripFrontmatter = (content) => {
 17	  const match = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
 18	  if (!match) return { frontmatter: {}, content };
 19	
 20	  const frontmatterStr = match[1];
 21	  const body = match[2];
 22	  const frontmatter = {};
 23	
 24	  for (const line of frontmatterStr.split('\n')) {
 25	    const colonIdx = line.indexOf(':');
 26	    if (colonIdx > 0) {
 27	      const key = line.slice(0, colonIdx).trim();
 28	      const value = line.slice(colonIdx + 1).trim().replace(/^["']|["']$/g, '');
 29	      frontmatter[key] = value;
 30	    }
 31	  }
 32	
 33	  return { frontmatter, content: body };
 34	};
 35	
 36	// Normalize a path: trim whitespace, expand ~, resolve to absolute
 37	const normalizePath = (p, homeDir) => {
 38	  if (!p || typeof p !== 'string') return null;
 39	  let normalized = p.trim();
 40	  if (!normalized) return null;
 41	  if (normalized.startsWith('~/')) {
 42	    normalized = path.join(homeDir, normalized.slice(2));
 43	  } else if (normalized === '~') {
 44	    normalized = homeDir;
 45	  }
 46	  return path.resolve(normalized);
 47	};
 48	
 49	// Module-level cache for bootstrap content.
 50	// The SKILL.md file does not change during a session, so reading + parsing it
 51	// once eliminates redundant fs.existsSync + fs.readFileSync + regex work on
 52	// every agent step.  See #1202 for the full analysis.
 53	let _bootstrapCache = undefined; // undefined = not yet loaded, null = file missing
 54	
 55	export const SuperpowersPlugin = async ({ client, directory }) => {
 56	  const homeDir = os.homedir();
 57	  const superpowersSkillsDir = path.resolve(__dirname, '../../skills');
 58	  const envConfigDir = normalizePath(process.env.OPENCODE_CONFIG_DIR, homeDir);
 59	  const configDir = envConfigDir || path.join(homeDir, '.config/opencode');
 60	
 61	  // Helper to generate bootstrap content (cached after first call)
 62	  const getBootstrapContent = () => {
 63	    // Return cached result on subsequent calls
 64	    if (_bootstrapCache !== undefined) return _bootstrapCache;
 65	
 66	    // Try to load using-superpowers skill
 67	    const skillPath = path.join(superpowersSkillsDir, 'using-superpowers', 'SKILL.md');
 68	    if (!fs.existsSync(skillPath)) {
 69	      _bootstrapCache = null;
 70	      return null;
 71	    }
 72	
 73	    const fullContent = fs.readFileSync(skillPath, 'utf8');
 74	    const { content } = extractAndStripFrontmatter(fullContent);
 75	
 76	    const toolMapping = `**Tool Mapping for OpenCode:**
 77	When skills request actions, substitute OpenCode equivalents:
 78	- Create or update todos → \`todowrite\`
 79	- \`Subagent (general-purpose):\` → \`task\` with \`subagent_type: "general"\`
 80	- Invoke a skill → OpenCode's native \`skill\` tool
 81	- Read files → \`read\`
 82	- Create, edit, or delete files → \`apply_patch\`
 83	- Run shell commands → \`bash\`
 84	- Search files → \`grep\`, \`glob\`
 85	- Fetch a URL → \`webfetch\`
 86	
 87	Use OpenCode's native \`skill\` tool to list and load skills.`;
 88	
 89	    _bootstrapCache = `<EXTREMELY_IMPORTANT>
 90	You have superpowers.
 91	
 92	**IMPORTANT: The using-superpowers skill content is included below. It is ALREADY LOADED - you are currently following it. Do NOT use the skill tool to load "using-superpowers" again - that would be redundant.**
 93	
 94	${content}
 95	
 96	${toolMapping}
 97	</EXTREMELY_IMPORTANT>`;
 98	
 99	    return _bootstrapCache;
100	  };
101	
102	  return {
103	    // Inject skills path into live config so OpenCode discovers superpowers skills
104	    // without requiring manual symlinks or config file edits.
105	    // This works because Config.get() returns a cached singleton — modifications
106	    // here are visible when skills are lazily discovered later.
107	    config: async (config) => {
108	      config.skills = config.skills || {};
109	      config.skills.paths = config.skills.paths || [];
110	      if (!config.skills.paths.includes(superpowersSkillsDir)) {
111	        config.skills.paths.push(superpowersSkillsDir);
112	      }
113	    },
114	
115	    // Inject bootstrap into the first user message of each session.
116	    // Using a user message instead of a system message avoids:
117	    //   1. Token bloat from system messages repeated every turn (#750)
118	    //   2. Multiple system messages breaking Qwen and other models (#894)
119	    //
120	    // The hook fires on every agent step (not just every turn) because
121	    // opencode's prompt.ts reloads messages from DB each step.  Fresh message
122	    // arrays may need injection again, so getBootstrapContent() must not do
123	    // repeated disk work.
124	    'experimental.chat.messages.transform': async (_input, output) => {
125	      const bootstrap = getBootstrapContent();
126	      if (!bootstrap || !output.messages.length) return;
127	      const firstUser = output.messages.find(m => m.info.role === 'user');
128	      if (!firstUser || !firstUser.parts.length) return;
129	
130	      // Guard: skip if first user message already contains bootstrap.
131	      // This prevents double injection when OpenCode passes an already
132	      // transformed in-memory message array through the hook again.
133	      if (firstUser.parts.some(p => p.type === 'text' && p.text.includes('EXTREMELY_IMPORTANT'))) return;
134	
135	      const ref = firstUser.parts[0];
136	      firstUser.parts.unshift({ ...ref, type: 'text', text: bootstrap });
137	    }
138	  };
139	};

